cd /app; for f in seeds/*.csv; do python3 - $f <<'E'
import sys
b=open(sys.argv[1],'rb').read()
try: b.decode('utf-8'); print(sys.argv[1],'utf8 ok', b[:3]==b'\xef\xbb\xbf', b.count(b'\r'))
except Exception as e: print(sys.argv[1],'not utf8',e)
try: b.decode('cp1252')
except Exception as e: print(' cp1252 fail',e)
E
done; python3 tools/stratum.py build 2>&1 | tail -5; grep -c . seeds/*.csv

